mapper.select:
select t.party_a,t.party_a partyA,t.a_link,t.a_link aLink,t.a_contacts,t.a_contacts
aContacts,t.partya_id,t.partya_id partyaId,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id storeId,
t.community_id, t.community_id communityId,
t.short_name shortName, t.credit_code creditCode, t.legal_person legalPerson, t.bank_name bankName,
t.bank_account bankAccount, t.contact_person contactPerson, t.contact_tel contactTel,
ifnull(t.seal_flag,'0') sealFlag, ifnull(t.default_flag,'0') defaultFlag, t.create_time createTime
from contract_partya t
where 1 =1

    and t.party_a like concat('%',#{partyA},'%')


    and (t.party_a like concat('%',#{partyALike},'%') or t.short_name like concat('%',#{partyALike},'%'))


    and t.a_link= #{aLink}


    and t.a_contacts like concat('%',#{aContacts},'%')


    and t.partya_id= #{partyaId}


    and t.credit_code= #{creditCode}


    and ifnull(t.default_flag,'0') = #{defaultFlag}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.community_id= #{communityId}

order by ifnull(t.default_flag,'0') desc, t.create_time desc

    limit #{page}, #{row}

