    , t.credit_code= #{creditCode}


    , t.legal_person= #{legalPerson}


    , t.bank_name= #{bankName}


    , t.bank_account= #{bankAccount}


    , t.contact_person= #{contactPerson}


    , t.contact_tel= #{contactTel}


    , t.seal_flag= #{sealFlag}


    , t.default_flag= #{defaultFlag}

where 1=1

