mapper.update:
update contract_partya t set t.default_flag = '0'
where t.status_cd = '0' and ifnull(t.default_flag, '0') = '1'

    and t.store_id = #{storeId}


    and t.community_id = #{communityId}


    and t.partya_id <> #{partyaId}
